struct FHash {
 FSHA1 State;
 void Int(int32 V){uint32 U=uint32(V);uint8 B[]={uint8(U),uint8(U>>8),uint8(U>>16),uint8(U>>24)};State.Update(B,4);}
 void Float(float V){uint32 U=0;FMemory::Memcpy(&U,&V,4);Int(int32(U));}
 void Vec(const FVector3f& V){Float(V.X);Float(V.Y);Float(V.Z);}
 void Text(const FString& V){FTCHARToUTF8 S(*V);Int(S.Length());State.Update(reinterpret_cast<const uint8*>(S.Get()),S.Length());}
 FString End(){State.Final();FSHAHash H;State.GetHash(H.Hash);return H.ToString().ToLower();}
};
FString BytesSha1(const TArray<uint8>& Bytes){FSHAHash H;FSHA1::HashBuffer(Bytes.GetData(),Bytes.Num(),H.Hash);return H.ToString().ToLower();}
FString FileSha1(const FString& Path){TArray<uint8> B;return FFileHelper::LoadFileToArray(B,*Path)?BytesSha1(B):FString();}
FString WholeDescription(const FMeshDescription& MD){FMeshDescription Copy=MD;TArray<uint8> B;FMemoryWriter Writer(B,true);Copy.Serialize(Writer);Writer.Close();return BytesSha1(B);}
TSharedPtr<FJsonObject> Obj(const TSharedPtr<FJsonObject>& J,const TCHAR* Name){const TSharedPtr<FJsonObject>* V=nullptr;return J.IsValid()&&J->TryGetObjectField(Name,V)?*V:nullptr;}
const TArray<TSharedPtr<FJsonValue>>* Array(const TSharedPtr<FJsonObject>& J,const TCHAR* Name){const TArray<TSharedPtr<FJsonValue>>* V=nullptr;return J.IsValid()&&J->TryGetArrayField(Name,V)?V:nullptr;}
bool Vector(const TSharedPtr<FJsonObject>& J,const TCHAR* Name,FVector3d& Out){const auto* A=Array(J,Name);if(!A||A->Num()!=3)return false;double V[3];for(int32 I=0;I<3;++I)if(!(*A)[I]->TryGetNumber(V[I])||!FMath::IsFinite(V[I]))return false;Out=FVector3d(V[0],V[1],V[2]);return true;}
FString PositionKey(const FVector3d& P){return FString::Printf(TEXT("%lld,%lld,%lld"),FMath::RoundToInt64(P.X*Quantization),FMath::RoundToInt64(P.Y*Quantization),FMath::RoundToInt64(P.Z*Quantization));}
FString TriangleKey(const FString& Slot,const FString (&Corners)[3]){TArray<FString> Sorted={Corners[0],Corners[1],Corners[2]};Sorted.Sort();return Slot+TEXT("|")+FString::Join(Sorted,TEXT("|"));}
