TSharedPtr<FJsonObject> RowSample(const FRenderRow& Row,const UStaticMesh* Mesh,bool Frame){auto J=MakeShared<FJsonObject>();FHash H;for(uint32 U:Row.Bits)H.Int(int32(U));J->SetStringField(TEXT("row_sha1"),H.End());const int32 Material=Row.Bits.Num()>1?int32(Row.Bits[0]):-1,UV=Row.Bits.Num()>1?int32(Row.Bits[1]):0;J->SetNumberField(TEXT("material_index"),Material);J->SetStringField(TEXT("material_slot"),Mesh->GetStaticMaterials().IsValidIndex(Material)?Mesh->GetStaticMaterials()[Material].MaterialSlotName.ToString():TEXT("invalid"));auto VectorAt=[&](int32 At,int32 Count){TArray<TSharedPtr<FJsonValue>> V;for(int32 K=0;K<Count&&Row.Bits.IsValidIndex(At+K);++K)V.Add(MakeShared<FJsonValueNumber>(BitsFloat(Row.Bits[At+K])));return V;};J->SetArrayField(TEXT("first_corner_position_cm"),VectorAt(2,3));if(Frame){J->SetArrayField(TEXT("first_corner_tangent_x_xyzw"),VectorAt(2+3+2*UV,4));J->SetArrayField(TEXT("first_corner_tangent_z_xyzw"),VectorAt(2+3+2*UV+4,4));}return J;}
bool SameRows(const TArray<FRenderRow>& A,const TArray<FRenderRow>& B,const UStaticMesh* Mesh,bool Frame,TSharedPtr<FJsonObject> Details){int32 I=0,J=0,Left=0,Right=0;TArray<TSharedPtr<FJsonValue>> Examples;while(I<A.Num()||J<B.Num()){const int32 C=I==A.Num()?1:J==B.Num()?-1:CompareBits(A[I].Bits,B[J].Bits);if(C==0){++I;++J;continue;}const bool SourceOnly=C<0;const auto& Row=SourceOnly?A[I++]:B[J++];SourceOnly?++Left:++Right;if(Examples.Num()<8){auto E=RowSample(Row,Mesh,Frame);E->SetStringField(TEXT("side"),SourceOnly?TEXT("source_only"):TEXT("derived_only"));Examples.Add(MakeShared<FJsonValueObject>(E));}}Details->SetNumberField(TEXT("source_only_rows"),Left);Details->SetNumberField(TEXT("derived_only_rows"),Right);Details->SetArrayField(TEXT("examples"),Examples);return Left==0&&Right==0;}

bool SourceDegenerateTangent(const FVector3f& X,const FVector3f& N){const double NS=N.SizeSquared(),TS=X.SizeSquared();return NS>1.e-12&&(TS<=1.e-12||double(FVector3f::CrossProduct(N,X).SizeSquared())<=1.e-12*NS*TS);}
struct FFrameDelta {bool Geometry=false,WExact=true,TangentsAllowed=true;double N=0,T=0,NAngle=0,TAngle=0,RegularT=0,RegularTAngle=0,RepairedT=0,RepairedTAngle=0;int32 SourceCorner=0,DerivedCorner=0,RepairedCorners=0;};
FRenderRow FrameGeometry(const FRenderRow& R){const int32 UV=int32(R.Bits[1]),Width=3+2*UV,Stride=Width+8;TArray<uint32> C[3];for(int32 K=0;K<3;++K)C[K].Append(R.Bits.GetData()+2+K*Stride,Width);return CyclicRow(int32(R.Bits[0]),UV,C);}
