 if(A.Bits.Num()<2||B.Bits.Num()<2||A.Bits[0]!=B.Bits[0]||A.Bits[1]!=B.Bits[1])return false;const int32 Width=3+2*int32(A.Bits[1]),Stride=Width+8;bool HaveBest=false;const double HalfStep=.5*(Bound-2.e-6)+2.e-6,BasisError=2*FMath::Sqrt(3.)*HalfStep+3*HalfStep*HalfStep;
