struct FTriangleSpec {FString Positions[3];FVector3f Normals[3];};
struct FDigests {FString Positions,Topology,UV,NonCabinFrames,Materials,AllAttributes;};
FDigests Digests(const FMeshDescription& MD,const UStaticMesh* Mesh,const TSet<FVertexInstanceID>& Cabin){
 FStaticMeshConstAttributes A(MD);const auto P=A.GetVertexPositions();const auto N=A.GetVertexInstanceNormals(),T=A.GetVertexInstanceTangents();const auto UV=A.GetVertexInstanceUVs();const auto Slots=A.GetPolygonGroupMaterialSlotNames();FHash HP,HT,HU,HN;
 HP.Int(MD.Vertices().Num());for(auto ID:MD.Vertices().GetElementIDs()){HP.Int(ID.GetValue());HP.Vec(P[ID]);}
 HT.Int(MD.VertexInstances().Num());for(auto ID:MD.VertexInstances().GetElementIDs()){HT.Int(ID.GetValue());HT.Int(MD.GetVertexInstanceVertex(ID).GetValue());}
 HT.Int(MD.Triangles().Num());for(auto ID:MD.Triangles().GetElementIDs()){HT.Int(ID.GetValue());HT.Int(MD.GetTrianglePolygon(ID).GetValue());HT.Int(MD.GetTrianglePolygonGroup(ID).GetValue());for(auto VI:MD.GetTriangleVertexInstances(ID))HT.Int(VI.GetValue());}
 HT.Int(MD.PolygonGroups().Num());for(auto ID:MD.PolygonGroups().GetElementIDs()){HT.Int(ID.GetValue());HT.Text(Slots[ID].ToString());}
 HU.Int(UV.GetNumChannels());for(auto VI:MD.VertexInstances().GetElementIDs()){HU.Int(VI.GetValue());for(int32 Channel=0;Channel<UV.GetNumChannels();++Channel){const FVector2f Value=UV.Get(VI,Channel);HU.Float(Value.X);HU.Float(Value.Y);}}
 for(auto VI:MD.VertexInstances().GetElementIDs())if(!Cabin.Contains(VI)){HN.Int(VI.GetValue());HN.Vec(N[VI]);HN.Vec(T[VI]);}
 return {HP.End(),HT.End(),HU.End(),HN.End(),MaterialHash(Mesh),WholeDescription(MD)};
}
TSharedPtr<FJsonObject> DigestJson(const FDigests& H){auto J=MakeShared<FJsonObject>();J->SetStringField(TEXT("positions_sha1"),H.Positions);J->SetStringField(TEXT("topology_sha1"),H.Topology);J->SetStringField(TEXT("uv_sha1"),H.UV);J->SetStringField(TEXT("non_cabin_frames_sha1"),H.NonCabinFrames);J->SetStringField(TEXT("materials_sha1"),H.Materials);J->SetStringField(TEXT("all_mesh_description_attributes_sha1"),H.AllAttributes);return J;}
bool Preserved(const FDigests& A,const FDigests& B){return A.Positions==B.Positions&&A.Topology==B.Topology&&A.UV==B.UV&&A.Materials==B.Materials;}

